from collections import defaultdict

def exact_cover_cells(g, allow_br=True):
 cells={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}
 places=[]
 # squares and Ls label by missing corner
 for r in range(6):
  for c in range(6):
   box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
   if box <= cells: places.append((1,box))
   for miss,lab in [( (r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
    s=box-{miss}
    if s<=cells and (lab!=5 or allow_br): places.append((lab,s))
 bycell=defaultdict(list)
 for p in places:
  for cell in p[1]: bycell[cell].append(p)
 sols=[]
 def rec(rem,sol):
  if not rem:
   sols.append(sol); return
  cell=min(rem,key=lambda x:sum(s<=rem for _,s in bycell[x]))
  for p in bycell[cell]:
   if p[1]<=rem: rec(rem-p[1],sol+[p])
 rec(cells,[])
 return sols
