program='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    pieces = []
    corner_colors = {(0, 0): 2, (1, 0): 3, (0, 1): 4, (1, 1): 5}
    for r in range(rows - 1):
        for c in range(cols - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= cells:
                pieces.append((1, box))
            for (dr, dc), color in corner_colors.items():
                shape = box - {(r + dr, c + dc)}
                if shape <= cells:
                    pieces.append((color, shape))

    by_cell = {cell: [] for cell in cells}
    for piece in pieces:
        for cell in piece[1]:
            by_cell[cell].append(piece)

    def search(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(shape <= remaining for _, shape in by_cell[p]))
        for piece in by_cell[cell]:
            color, shape = piece
            if shape <= remaining:
                tail = search(remaining - shape)
                if tail is not None:
                    return [piece] + tail
        return None

    solution = search(cells)
    if solution is None:
        raise ValueError("Input cannot be tiled by 2x2 squares and L trominoes")
    output = [[0] * cols for _ in range(rows)]
    for color, shape in solution:
        for r, c in shape:
            output[r][c] = color
    return output
'''
